import re

def parse_total_and_card(content):
    m_total=re.search(r'Total\s*=>\s*\$\s*([0-9]+(?:\.[0-9]+)?)', content)
    m_card=re.search(r'Paid by Card\s*=>\s*\*\*\*\*([0-9]{4})', content)
    total=Decimal(m_total.group(1)) if m_total else None
    card_last4=m_card.group(1) if m_card else None
    return total, card_last4

parsed={}
for name,content in contents.items():
    total, card4=parse_total_and_card(content)
    parsed[name]={'total':total,'card_last4':card4}

print('parsed',parsed)

wf_total=sum(v['total'] for v in parsed.values() if v['card_last4']==wf_last4)
